import{_ as a,a0 as s,w as i,s as d,ao as p,I as o,x as e,a1 as r,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const h=JSON.parse('{"title":"在RHEL/CentOS 5/6下停用按下Ctrl-Alt-Del 重啓系統的功能 | LCTT x X-CMD","titleTemplate":false,"description":"在RHEL/CentOS 5/6下停用按下Ctrl-Alt-Del 重啓系統的功能 | LCTT (201410) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在RHEL/CentOS 5/6下停用按下Ctrl-Alt-Del 重啓系統的功能 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在RHEL/CentOS 5/6下停用按下Ctrl-Alt-Del 重啓系統的功能 | LCTT (201410) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201410/20140818 Disable reboot using Ctrl-Alt-Del Keys in RHEL or CentOS","title":"在RHEL/CentOS 5/6下停用按下Ctrl-Alt-Del 重啓系統的功能","tag":"201410","desc":""},"relativePath":"201410/20140818 Disable reboot using Ctrl-Alt-Del Keys in RHEL or CentOS.md","filePath":"[post].md"}'),C={name:"201410/20140818 Disable reboot using Ctrl-Alt-Del Keys in RHEL or CentOS.md"};function u(g,t,c,L,T,x){const l=s("Link");return i(),d("div",null,[t[13]||(t[13]=p(`<h1 id="在rhel-centos-5-6下停用按下ctrl-alt-del-重啓系統的功能" tabindex="-1">在RHEL/CentOS 5/6下停用按下Ctrl-Alt-Del 重啓系統的功能 <a class="header-anchor" href="#在rhel-centos-5-6下停用按下ctrl-alt-del-重啓系統的功能" aria-label="Permalink to “在RHEL/CentOS 5/6下停用按下Ctrl-Alt-Del 重啓系統的功能”">​</a></h1><p>在Linux裏，由於對安全的考慮，我們允許任何人按下<strong>Ctrl-Alt-Del</strong>來<strong>重啓</strong>系統。但是在生產環境中，應該停用按下Ctrl-Alt-Del 重啓系統的功能。</p><p>在這篇文章裏，我們將要介紹如何在RHEL和CentOS下停用該熱鍵。</p><h3 id="在rhel-5-x和centos-5-x下" tabindex="-1">在RHEL 5.X和CentOS 5.X下 <a class="header-anchor" href="#在rhel-5-x和centos-5-x下" aria-label="Permalink to “在RHEL 5.X和CentOS 5.X下”">​</a></h3><p>保護<strong>init</strong>進程免於<strong>Ctrl-Alt-Del</strong>,像下面一樣編輯&#39;<strong>/etc/inittab</strong>&#39;裏由&#39;<strong>ca::ctrlaltdel</strong>:&#39;開頭的一行:</p><pre><code>[root@localhost ~]# cat /etc/inittab
# Trap CTRL-ALT-DELETE
#ca::ctrlaltdel:/sbin/shutdown -t3 -r now
</code></pre><p>我們還可以改變&#39;ca::ctrlaltdel:&#39;這行來輸出日誌 ,如果任何人想用該熱鍵重啓服務器,就會有日誌,</p><pre><code>[root@localhost ~]# cat /etc/inittab
# Trap CTRL-ALT-DELETE
ca::ctrlaltdel:/bin/logger -p authpriv.warning -t init &quot;Console-invoked Ctrl-Alt-Del was ignored&quot;
</code></pre><h3 id="在rhel6-x和centos-6-x下" tabindex="-1">在RHEL6.X和CentOS 6.X下 <a class="header-anchor" href="#在rhel6-x和centos-6-x下" aria-label="Permalink to “在RHEL6.X和CentOS 6.X下”">​</a></h3><p>在RHEL6.X和CentOS 6.X下, 該熱鍵的行為由&#39;<strong>/etc/init/control-alt-delete.conf</strong>&#39;控制.</p><p><strong>第一步</strong> 在變化之前，先用下列命令備份配置</p><pre><code>[root@localhost ~]# cp -v /etc/init/control-alt-delete.conf /etc/init/control-alt-delete.override
</code></pre><p><strong>第二步</strong>編輯文件，把&#39;exec /sbin/shutdown&#39;這一行用下方配置代替，這個配置會在每次按下Ctrl-Alt-Del 時輸出日誌:</p><pre><code>[root@localhost ~]# cat /etc/init/control-alt-delete.conf
exec /usr/bin/logger -p authpriv.notice -t init &quot;Ctrl-Alt-Del was pressed and ignored&quot; 
</code></pre><hr>`,15)),o("p",null,[t[1]||(t[1]=e("via: ",-1)),r(l,{href:"http://www.linuxtechi.com/disable-reboot-using-ctrl-alt-del-keys/"},{default:n(()=>[...t[0]||(t[0]=[e("http://www.linuxtechi.com/disable-reboot-using-ctrl-alt-del-keys/",-1)])]),_:1})]),o("p",null,[t[5]||(t[5]=e("作者：",-1)),r(l,{href:"http://www.linuxtechi.com/author/pradeep/"},{default:n(()=>[...t[2]||(t[2]=[e("Pradeep Kumar",-1)])]),_:1}),t[6]||(t[6]=e(" 譯者：",-1)),r(l,{href:"https://github.com/2q1w2007"},{default:n(()=>[...t[3]||(t[3]=[e("2q1w2007",-1)])]),_:1}),t[7]||(t[7]=e(" 校對：",-1)),r(l,{href:"https://github.com/wxy"},{default:n(()=>[...t[4]||(t[4]=[e("wxy",-1)])]),_:1})]),o("p",null,[t[10]||(t[10]=e("本文由 ",-1)),r(l,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[8]||(t[8]=[e("LCTT",-1)])]),_:1}),t[11]||(t[11]=e(" 原創翻譯，",-1)),r(l,{href:"http://linux.cn/"},{default:n(()=>[...t[9]||(t[9]=[e("Linux中國",-1)])]),_:1}),t[12]||(t[12]=e(" 榮譽推出",-1))])])}const m=a(C,[["render",u]]);export{h as __pageData,m as default};
